1	// Applies the repository's design tokens as CSS custom properties.
2	// resources/jusprin/ui/design-tokens.json is the implementation source of
3	// truth; the stylesheet must use var(--...) rather than literal colors,
4	// radii, or type metrics. styles.test.ts enforces that on the stylesheet.
5	//
6	// The universal part lives in WebShared/tokens.ts, shared with the Home page.
7	// Only the Agent page's own component variables are written here.
8	
9	import tokens from '@resources/jusprin/ui/design-tokens.json';
10	import { applySharedStaticTokens, sharedStaticVariableNames } from '@shared/tokens';
11	
12	export { applyAppearance } from '@shared/tokens';
13	
14	// Every --font-*, --button-*, and Agent-page variable applyStaticTokens
15	// writes, so a test can check that the stylesheet only asks for variables
16	// that exist.
17	export function staticVariableNames(): string[] {
18	  return [...sharedStaticVariableNames(), '--thread-row-line-gap'];
19	}
20	
21	// In addition to the shared radii, fonts, and button paddings:
22	//   --thread-row-line-gap the space between a thread row's title and its
23	//                         metadata line, an internal size of the row
24	export function applyStaticTokens(): void {
25	  applySharedStaticTokens();
26	  const { component } = tokens as unknown as { component: { threadRow: { lineGap: number } } };
27	  document.documentElement.style.setProperty('--thread-row-line-gap', `${component.threadRow.lineGap}px`);
28	}
29

1	// Applies the repository's design tokens as CSS custom properties. The
2	// universal part lives in WebShared/tokens.ts; Home adds its own card
3	// geometry, guarded in tests/brand/test_brand_tokens.cpp:
4	//   --project-card-<name>   min/max width, footer height, radius
5	//   --project-card-thumbnail-aspect  the unitless `4 / 3` for aspect-ratio
6	//   --printer-card-<name>   column width, progress height, radius
7	//   --status-dot-size, --swatch-size, --swatch-radius
8	
9	import tokens from '@resources/jusprin/ui/design-tokens.json';
10	import {
11	  applyPixelTokens,
12	  applySharedStaticTokens,
13	  elevationVariableNames,
14	  pixelVariableNames,
15	  sharedStaticVariableNames,
16	} from '@shared/tokens';
17	
18	export { applyAppearance } from '@shared/tokens';
19	
20	interface CardTokens {
21	  component: {
22	    projectCard: Record<string, number>;
23	    printerCard: Record<string, number>;
24	    statusDot: { size: number };
25	    swatch: Record<string, number>;
26	    icon: { sizes: number[] };
27	  };
28	}
29	
30	const { component } = tokens as unknown as CardTokens;
31	
32	// The aspect ratio is a pair of unitless numbers, not a length, so it is
33	// written as one `4 / 3` variable rather than two pixel variables.
34	const ASPECT = '--project-card-thumbnail-aspect';
35	
36	// An inline glyph -- the printer beside a name, the monitor on its button --
37	// is the smallest size on the documented icon scale, so it sits on the text
38	// line rather than beside it.
39	const GLYPH = '--glyph-size';
40	
41	function pixelSection(section: Record<string, number>): Record<string, number> {
42	  const { thumbnailAspectWidth, thumbnailAspectHeight, ...rest } = section;
43	  void thumbnailAspectWidth;
44	  void thumbnailAspectHeight;
45	  return rest;
46	}
47	
48	export function staticVariableNames(): string[] {
49	  return [
50	    ...sharedStaticVariableNames(),
51	    ...pixelVariableNames('project-card', pixelSection(component.projectCard)),
52	    ASPECT,
53	    ...pixelVariableNames('printer-card', component.printerCard),
54	    ...pixelVariableNames('status-dot', component.statusDot),
55	    ...pixelVariableNames('swatch', component.swatch),
56	    ...elevationVariableNames(),
57	    GLYPH,
58	  ];
59	}
60	
61	export function applyStaticTokens(): void {
62	  applySharedStaticTokens();
63	  const card = component.projectCard;
64	  applyPixelTokens('project-card', pixelSection(card));
65	  document.documentElement.style.setProperty(
66	    ASPECT,
67	    `${card.thumbnailAspectWidth} / ${card.thumbnailAspectHeight}`,
68	  );
69	  applyPixelTokens('printer-card', component.printerCard);
70	  applyPixelTokens('status-dot', component.statusDot);
71	  applyPixelTokens('swatch', component.swatch);
72	  document.documentElement.style.setProperty(GLYPH, `${Math.min(...component.icon.sizes)}px`);
73	}
74

1	// Typed view of the jusprin-agent-bridge protocol. The canonical shared
2	// source is resources/jusprin/agent/protocol.json; the constants here are
3	// derived from it at build time so the page and the native host cannot
4	// silently disagree about the protocol name or version.
5	
6	import protocolJson from '@resources/jusprin/agent/protocol.json';
7	
8	export const PROTOCOL_NAME: string = protocolJson.name;
9	export const PROTOCOL_VERSION: number = protocolJson.version;
10	export const PAGE_CAPABILITIES: string[] = protocolJson.capabilities;
11	
12	export type PageMessageType =
13	  | 'hello'
14	  | 'state_request'
15	  | 'user_message'
16	  | 'stop_generation'
17	  | 'retry_message'
18	  | 'tool_decision'
19	  | 'tool_cancel'
20	  | 'create_conversation'
21	  | 'switch_conversation'
22	  | 'rename_conversation'
23	  | 'delete_conversation'
24	  | 'draft_update'
25	  | 'attach_file'
26	  | 'remove_attachment'
27	  | 'setup_check_key'
28	  | 'setup_cancel'
29	  | 'mcp_catalog'
30	  | 'mcp_preview'
31	  | 'mcp_connect'
32	  | 'reveal_path';
33	
34	export type HostMessageType =
35	  | 'hello_ack'
36	  | 'hello_reject'
37	  | 'state'
38	  | 'conversations_updated'
39	  | 'context'
40	  | 'appearance'
41	  | 'agent_status'
42	  | 'message_added'
43	  | 'assistant_started'
44	  | 'assistant_delta'
45	  | 'assistant_completed'
46	  | 'assistant_failed'
47	  | 'assistant_stopped'
48	  | 'tool_activity'
49	  | 'bridge_error'
50	  | 'attachment_updated'
51	  | 'setup_status'
52	  | 'mcp_catalog'
53	  | 'mcp_preview'
54	  | 'mcp_status'
55	  | 'change_added';
56	
57	export interface Envelope<T = unknown> {
58	  protocol: string;
59	  version: number;
60	  id: string;
61	  type: string;
62	  correlationId?: string;
63	  sessionId?: string;
64	  revision?: number;
65	  payload: T;
66	}
67	
68	// 'note' is the host's own voice: a short factual line the native shell posts
69	// when it changes something the reader should see in the thread (a spool swap,
70	// for example). It is never a turn -- no reply follows it, and the host never
71	// sends it to the model -- so it renders as a plain line, not a bubble.
72	export type MessageRole = 'user' | 'assistant' | 'note';
73	export type MessageStateName = 'complete' | 'streaming' | 'failed' | 'stopped';
74	export type AgentStatus = 'ready' | 'unavailable';
75	export type Appearance = 'light' | 'dark';
76	
77	export interface AgentErrorInfo {
78	  code: string;
79	  message: string;
80	  retryable: boolean;
81	}
82	
83	export interface WireMessage {
84	  id: string;
85	  role: MessageRole;
86	  state: MessageStateName;
87	  text: string;
88	  attempt: number;
89	  clientMessageId?: string;
90	  inReplyTo?: string;
91	  error?: AgentErrorInfo;
92	  attachments?: string[]; // sent attachment IDs, resolved against StatePayload.attachments
93	}
94	
95	// How a file entered the composer.
96	export type AttachmentSource = 'picker' | 'drop' | 'clipboard' | 'project';
97	
98	// The host's classification of an attachment. Model/project files go through
99	// Orca's native importer and reach the Agent as a native summary, never as
100	// decoded bytes; unknown/unsupported binaries are rejected visibly.
101	export type AttachmentKind =
102	  | 'text'
103	  | 'image'
104	  | 'svg'
105	  | 'pdf'
106	  | 'gcode'
107	  | 'model'
108	  | 'unsupported';
109	
110	// Lifecycle of one attachment. 'staged' is in the composer but not yet sent;
111	// 'sent' belongs to a durable user message; 'error' failed to decode/store.
112	export type AttachmentState = 'staged' | 'sent' | 'error';
113	
114	export interface AttachmentInfo {
115	  id: string;
116	  name: string; // original file name (display only)
117	  kind: AttachmentKind;
118	  mime: string;
119	  sizeBytes: number;
120	  source: AttachmentSource;
121	  state: AttachmentState;
122	  // Host-decoded preview, present where the kind supports it and the blob is
123	  // within the inline cap. Reconstructed from native state after a reload.
124	  previewText?: string; // text/gcode/svg source, truncated
125	  previewDataUrl?: string; // image thumbnails
126	  // A native, non-binary description of an imported model for Agent context.
127	  summary?: string;
128	  error?: { code: string; message: string };
129	}
130	
131	// Where a credential check has got to. 'verified' means the provider
132	// answered and the Agent is being connected; 'warning' is set when the key
133	// worked but could not be written to the machine's credential store.
134	export type SetupPhase = 'idle' | 'checking' | 'verified' | 'error';
135	
136	export interface SetupStatusPayload {
137	  phase: SetupPhase;
138	  provider?: string;
139	  elapsedMs?: number;
140	  error?: AgentErrorInfo;
141	  warning?: string;
142	}
143	
144	export interface McpToolInfo {
145	  id: string;
146	  name: string;
147	  subtitle?: string;
148	  detected: boolean;
149	  cli: boolean;
150	  text: string;
151	  configPath?: string;
152	}
153	
154	export interface McpCatalogPayload {
155	  tools: McpToolInfo[];
156	  liveUrl?: string;
157	  helperPresent: boolean;
158	  startupError?: string;
159	}
160	
161	export interface McpPreviewPayload {
162	  toolId: string;
163	  path: string;
164	  // Absent when the file has no JusPrin entry yet. The host omits the field
165	  // rather than sending a serialised null, so "nothing there yet" stays
166	  // distinguishable from a real entry the user should read.
167	  previous?: string;
168	  next: string;
169	  root: string;
170	}
171	
172	export interface McpStatusPayload {
173	  phase: 'idle' | 'writing' | 'saved' | 'error';
174	  toolId?: string;
175	  backup?: string;
176	  diagnostic?: string;
177	  error?: AgentErrorInfo;
178	}
179	
180	// Time and material for one plate's current slice. Null whenever that plate
181	// holds no valid slice result: OrcaSlicer has no background slicing, so there
182	// is no honest estimate before Slice and the card omits the row rather than
183	// showing a zero. materialCost is null on its own whenever the filament
184	// profile carries no price, which is the default.
185	export interface SliceEstimateInfo {
186	  printTimeSeconds: number;
187	  materialGrams: number;
188	  materialCost: number | null;
189	}
190	
191	// One process setting whose value in force differs from the preset it came
192	// from. The length of the list is the setup card's "N changes"; the entries
193	// are what the card shows when it is opened.
194	export interface PresetDeltaInfo {
195	  key: string;
196	  label: string;
197	  preset: string;
198	  value: string;
199	  // Who put this value in force. 'user' unless the host can prove the agent
200	  // wrote this exact value, so a setting the agent once set and you have since
201	  // edited by hand reads as yours again.
202	  origin: 'agent' | 'user';
203	}
204	
205	// What the estimate is worth right now. The number is kept in all three: a
206	// slice in flight or invalidated does not make the last honest figure
207	// worthless, and blanking it kills the comparison the reader is making.
208	export type EstimateStatus = 'current' | 'recomputing' | 'stale';
209	
210	export interface WorkspaceContext {
211	  sessionId: string;
212	  revision: number;
213	  projectName: string;
214	  projectDirty: boolean;
215	  // `process` is the preset the setting deltas are measured against, so it is
216	  // the name the setup card shows; `preset` is the machine and `filament` the
217	  // spool. Empty for a non-FFF printer, which has no process preset.
218	  printer: { preset: string; filament: string; process: string };
219	  plates: {
220	    id: string;
221	    name: string;
222	    active: boolean;
223	    sliced: boolean;
224	    estimate: SliceEstimateInfo | null;
225	    estimateStatus: EstimateStatus;
226	    // Which of the user's actions invalidated the slice, when it is known.
227	    // Empty otherwise: the card says nothing rather than attributing the loss
228	    // to something the reader did not do.
229	    invalidatedBy: string;
230	    objects: { id: string; name: string; instances: number; selected: boolean }[];
231	  }[];
232	  selection: { status: 'none' | 'objects' | 'unsupported'; objectIds: string[] };
233	  history: { canUndo: boolean; canRedo: boolean };
234	  presetDeltas: PresetDeltaInfo[];
235	  // ISO 4217 code from the machine's regional settings, empty when the OS does
236	  // not say. OrcaSlicer itself has no currency concept, so this is the only
237	  // thing that says what a cost is denominated in.
238	  currency: string;
239	  // The agent's restatement of what this chat asked the setup to be, in the
240	  // user's words. Empty until a change is applied: talking does not write it.
241	  setupIntent: string;
242	}
243	
244	// Lifecycle of one native tool action. Terminal states are 'succeeded',
245	// 'failed', 'cancelled', and 'rejected'; a stale proposal arrives as
246	// state 'failed' with error code 'stale_revision'.
247	export type ToolStateName =
248	  | 'pending'
249	  | 'approved'
250	  | 'running'
251	  | 'succeeded'
252	  | 'failed'
253	  | 'cancelled'
254	  | 'rejected';
255	
256	export type ActionClassName = 'read_only' | 'mutation' | 'destructive';
257	
258	export interface ToolActivityInfo {
259	  actionId: string;
260	  correlationId: string; // assistant message or external adapter request
261	  source?: 'agent' | 'mcp'; // absent in older native builds: in-app Agent
262	  server: string;
263	  tool: string;
264	  title: string;
265	  arguments: Record<string, unknown>;
266	  actionClass: ActionClassName;
267	  requiresApproval: boolean;
268	  sessionId: string;
269	  expectedRevision: number;
270	  state: ToolStateName;
271	  progress: { current: number; total: number };
272	  result?: Record<string, unknown>;
273	  error?: { code: string; message: string };
274	}
275	
276	export interface ConversationInfo {
277	  id: string;
278	  title: string;
279	  createdAt: string;
280	  updatedAt?: string;
281	  preview?: string;
282	}
283	
284	// One entry of the change log: an edit the workspace reported, stored raw.
285	// The page merges consecutive identical edits into one row for display.
286	//   step     a real undo step; label is OrcaSlicer's step name, maybe empty
287	//   undo     label is the step undone;  redo: the step redone
288	//   setting  label is the setting's name; from/to/preset say the rest
289	//   preset   a whole preset was switched; label is the new preset
290	export type ChangeKind = 'step' | 'undo' | 'redo' | 'setting' | 'preset';
291	
292	export interface ChangeInfo {
