1	// Typed view of the jusprin-home-bridge protocol. The canonical shared source
2	// is resources/jusprin/home/protocol.json; the constants here are derived from
3	// it at build time so the page and the native host cannot silently disagree
4	// about the protocol name or version.
5	//
6	// The page owns its own chrome strings, as the Agent page does. The host sends
7	// data plus the few lines only it can phrase: a project's status text and a
8	// printer's connection and nozzle lines come from native code that already has
9	// the device facts and the translations.
10	
11	import protocolJson from '@resources/jusprin/home/protocol.json';
12	
13	export const PROTOCOL_NAME: string = protocolJson.name;
14	export const PROTOCOL_VERSION: number = protocolJson.version;
15	export const PAGE_CAPABILITIES: string[] = protocolJson.capabilities;
16	
17	export type PageMessageType =
18	  | 'hello'
19	  | 'state_request'
20	  | 'open_project'
21	  | 'new_project'
22	  | 'import_project'
23	  | 'launch_monitor'
24	  | 'add_printer';
25	
26	export type HostMessageType =
27	  | 'hello_ack'
28	  | 'hello_reject'
29	  | 'state'
30	  | 'projects'
31	  | 'printers'
32	  | 'appearance'
33	  | 'bridge_error';
34	
35	export type Appearance = 'light' | 'dark';
36	
37	// What a project card's status line means, separate from what it says. Only
38	// 'printing' earns a colored dot; every other state takes the plain line, so
39	// an idle project cannot be mistaken for a running one.
40	//
41	// 'unknown' is honest about the current state of the codebase: nothing records
42	// per-project slice state yet, so the host sends what it can derive (the
43	// recent-file modified time) under this kind. When a real store exists, the
44	// host starts sending the other kinds and this page needs no change.
45	export type ProjectStatusKind = 'unknown' | 'draft' | 'sliced' | 'printing' | 'completed';
46	
47	export interface ProjectStatus {
48	  kind: ProjectStatusKind;
49	  // Host-formatted and already translated; the page never composes it.
50	  text: string;
51	}
52	
53	export interface ProjectInfo {
54	  id: string;
55	  name: string;
56	  // Shown only as a tooltip: the card is titled by name.
57	  path: string;
58	  // A file: URL the host resolved from the .3mf thumbnail, absent when the
59	  // project carries none.
60	  thumbnailUrl?: string;
61	  status: ProjectStatus;
62	}
63	
64	export type PrinterState = 'idle' | 'printing' | 'offline';
65	
66	export interface SpoolInfo {
67	  // '#RRGGBB', from the fork-owned spool store.
68	  colour: string;
69	}
70	
71	export interface PrinterInfo {
72	  id: string;
73	  name: string;
74	  state: PrinterState;
75	  // Host-formatted status line, e.g. "Printing · 43% · 2h left". Present
76	  // whenever the host has something to say about the current job.
77	  statusText?: string;
78	  // 0-100, present only while printing; drives the progress bar's width.
79	  progressPercent?: number;
80	  connectionText?: string;
81	  nozzleText?: string;
82	  materialLabel?: string;
83	  spools: SpoolInfo[];
84	  canLaunchMonitor: boolean;
85	}
86	
87	export interface StatePayload {
88	  appearance: Appearance;
89	  projects: ProjectInfo[];
90	  printers: PrinterInfo[];
91	}
92	
93	export interface Envelope<T = unknown> {
94	  protocol: string;
95	  version: number;
96	  id: string;
97	  type: string;
98	  correlationId?: string;
99	  payload: T;
100	}
101	
102	export function isEnvelope(value: unknown): value is Envelope {
103	  if (typeof value !== 'object' || value === null) return false;
104	  const env = value as Record<string, unknown>;
105	  return (
106	    env.protocol === PROTOCOL_NAME &&
107	    typeof env.version === 'number' &&
108	    typeof env.id === 'string' &&
109	    typeof env.type === 'string'
110	  );
111	}
