// The transport, handshake, and message identity shared by every JusPrin web
// surface. It renders nothing and knows no page's message types: a page names
// its protocol once, and consumes the connection state and the validated host
// envelopes. Reload safety comes from the protocol design -- every hello is
// answered with complete native state.

export type ConnectionState =
  | 'connecting'
  | 'connected'
  | 'no-transport'
  | 'incompatible'
  | 'timeout';

export interface Envelope<T = unknown> {
  protocol: string;
  version: number;
  id: string;
  type: string;
  correlationId?: string;
  sessionId?: string;
  revision?: number;
  payload: T;
}

// Which protocol this page speaks, from its own protocol.json.
export interface ProtocolIdentity {
  name: string;
  version: number;
  capabilities: string[];
}

export interface Transport {
  post(json: string): void;
}

export interface BridgeClientOptions {
  // The native transport can appear slightly after the page starts running:
  // wx injects window.wx into an already-loading page from native code. The
  // client therefore re-polls this factory before declaring no-transport.
  getTransport: () => Transport | null;
  onEnvelope: (envelope: Envelope) => void;
  onConnectionChange: (state: ConnectionState, detail?: string) => void;
  handshakeTimeoutMs?: number;
  transportRetryMs?: number;
  transportRetryLimit?: number;
  // Injectable for deterministic tests.
  scheduleTimeout?: (fn: () => void, ms: number) => unknown;
  cancelTimeout?: (handle: unknown) => void;
}

declare global {
  interface Window {
    wx?: { postMessage(json: string): void };
    __jusprinBridge?: { deliver(envelope: unknown): void };
  }
}

export function nativeTransport(): Transport | null {
  if (typeof window !== 'undefined' && window.wx && typeof window.wx.postMessage === 'function') {
    return { post: (json) => window.wx!.postMessage(json) };
  }
  return null;
}

export function envelopeMatches(value: unknown, protocolName: string): value is Envelope {
  if (typeof value !== 'object' || value === null) return false;
  const env = value as Record<string, unknown>;
  return (
    env.protocol === protocolName &&
    typeof env.version === 'number' &&
    typeof env.id === 'string' &&
    typeof env.type === 'string'
  );
}

export class SharedBridgeClient {
  private readonly protocol: ProtocolIdentity;
  private readonly options: BridgeClientOptions;
  private nextId = 1;
  private handshakeHandle: unknown = null;
  private state: ConnectionState = 'connecting';
  private transport: Transport | null = null;
  private transportAttempts = 0;

  constructor(protocol: ProtocolIdentity, options: BridgeClientOptions) {
    this.protocol = protocol;
    this.options = options;
  }

  connectionState(): ConnectionState {
    return this.state;
  }

  start(): void {
    if (typeof window !== 'undefined') {
      window.__jusprinBridge = { deliver: (envelope: unknown) => this.deliver(envelope) };
    }
    this.beginHandshake();
  }

  retry(): void {
    this.transportAttempts = 0;
    this.beginHandshake();
  }

  private schedule(fn: () => void, ms: number): unknown {
    const schedule = this.options.scheduleTimeout ?? ((f, m) => setTimeout(f, m));
    return schedule(fn, ms);
  }

  private cancel(handle: unknown): void {
    const cancel = this.options.cancelTimeout ?? ((h) => clearTimeout(h as number));
    cancel(handle);
  }

  private beginHandshake(): void {
    this.transport = this.options.getTransport();
    if (!this.transport) {
      const limit = this.options.transportRetryLimit ?? 40;
      if (this.transportAttempts < limit) {
        this.transportAttempts += 1;
        this.setState('connecting');
        this.schedule(() => {
          if (this.state === 'connecting' && !this.transport) this.beginHandshake();
        }, this.options.transportRetryMs ?? 250);
      } else {
        this.setState('no-transport', 'The native message handler (window.wx) is not present.');
      }
      return;
    }
    this.setState('connecting');
    this.post('hello', {
      protocolVersions: [this.protocol.version],
      capabilities: this.protocol.capabilities,
    });
    const timeoutMs = this.options.handshakeTimeoutMs ?? 10000;
    if (this.handshakeHandle !== null) this.cancel(this.handshakeHandle);
    this.handshakeHandle = this.schedule(() => {
      if (this.state === 'connecting') {
        this.setState('timeout', 'The native host did not answer the hello handshake.');
      }
    }, timeoutMs);
  }

  send(type: string, payload: unknown): void {
    this.post(type, payload);
  }

  private post(type: string, payload: unknown): void {
    if (!this.transport) return;
    const envelope: Envelope = {
      protocol: this.protocol.name,
      version: this.protocol.version,
      id: `w-${this.nextId++}`,
      type,
      payload,
    };
    this.transport.post(JSON.stringify(envelope));
  }

  deliver(raw: unknown): void {
    if (!envelopeMatches(raw, this.protocol.name)) return; // not this protocol; ignore
    const envelope = raw;
    if (envelope.type === 'hello_ack') {
      this.cancelHandshakeTimer();
      this.setState('connected');
    } else if (envelope.type === 'hello_reject') {
      this.cancelHandshakeTimer();
      const payload = envelope.payload as { message?: string } | undefined;
      this.setState('incompatible', payload?.message ?? 'The host rejected this protocol version.');
    }
    this.options.onEnvelope(envelope);
  }

  private cancelHandshakeTimer(): void {
    if (this.handshakeHandle !== null) {
      this.cancel(this.handshakeHandle);
      this.handshakeHandle = null;
    }
  }

  private setState(state: ConnectionState, detail?: string): void {
    this.state = state;
    this.options.onConnectionChange(state, detail);
  }
}

// Guards the stylesheet's contract with resources/jusprin/ui/design-tokens.json:
// colors, radii, and type metrics resolve through the custom properties that
// tokens.ts emits, and spacing sits on the spacing scale. The file is read
// from disk on purpose: importing the CSS under Vitest yields an empty string,
// so a test written that way passes while asserting nothing.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { semanticVariableNames } from '@shared/tokens';
import { staticVariableNames } from './tokens';

const SPACING_SCALE = [0, 4, 8, 12, 16, 20, 24, 32, 40, 48];

const source = readFileSync(join(__dirname, 'styles.css'), 'utf8');

// Blank out comments but keep every newline so reported line numbers match
// the file.
const css = source.replace(/\/\*[\s\S]*?\*\//g, (comment) => comment.replace(/[^\n]/g, ' '));
const lines = css.split('\n');

// Line numbers (1-based) covered by an @font-face block, where font metrics
// are the declaration of the face itself rather than a use of it.
function fontFaceLines(): Set<number> {
  const covered = new Set<number>();
  let depth = 0;
  let inFontFace = false;
  lines.forEach((line, index) => {
    if (!inFontFace && /@font-face\b/.test(line)) inFontFace = true;
    if (inFontFace) covered.add(index + 1);
    for (const ch of line) {
      if (ch === '{') depth += 1;
      if (ch === '}') {
        depth -= 1;
        if (inFontFace && depth === 0) inFontFace = false;
      }
    }
  });
  return covered;
}

const exemptLines = fontFaceLines();

function offending(pattern: RegExp, extra?: (line: string) => boolean): string[] {
  const hits: string[] = [];
  lines.forEach((line, index) => {
    const number = index + 1;
    if (exemptLines.has(number)) return;
    if (pattern.test(line) && (!extra || extra(line))) hits.push(`${number}: ${line.trim()}`);
  });
  return hits;
}

describe('styles.css stays on the design tokens', () => {
  it('was actually read', () => {
    expect(source.trim().length).toBeGreaterThan(0);
  });

  it('carries no literal color', () => {
    expect(offending(/#[0-9a-fA-F]{3,8}\b|\b(rgba?|hsla?)\(/)).toEqual([]);
  });

  it('carries no pixel border-radius', () => {
    expect(offending(/border-radius\s*:[^;]*\d+px/)).toEqual([]);
  });

  // The patterns match after a `{` or `;` as well as at the start of a line,
  // so a single-line rule cannot slip past them.
  it('sets type only through the role variables', () => {
    expect(offending(/(?:^|[{;])\s*(font-size|line-height|font-weight)\s*:/)).toEqual([]);
    // A `font` shorthand with a literal size or line height would bypass the
    // check above.
    expect(offending(/(?:^|[{;])\s*font\s*:[^;]*\d+px/)).toEqual([]);
  });

  it('asks only for variables that tokens.ts emits', () => {
    const emitted = new Set([...staticVariableNames(), ...semanticVariableNames()]);
    expect(emitted).toContain('--font-body-bold');
    expect(emitted).toContain('--button-secondary-padding');
    expect(emitted).toContain('--action-primary-text');
    const requested = [
      ...css.matchAll(/var\((--(?:radius|font|button|action|text|surface|border|status)-[\w-]+)\)/g),
    ].map((m) => m[1]);
    expect(requested.length).toBeGreaterThan(0);
    expect(requested.filter((name) => !emitted.has(name))).toEqual([]);
  });

  it('keeps padding, margin, and gap on the spacing scale', () => {
    const offScale = offending(/^\s*(padding|margin|gap|row-gap|column-gap)(-[a-z]+)?\s*:/, (line) => {
      const value = line.replace(/^[^:]*:/, '');
      const pixels = [...value.matchAll(/(-?\d+(?:\.\d+)?)px/g)].map((m) => Math.abs(Number(m[1])));
      return pixels.some((px) => !SPACING_SCALE.includes(px));
    });
    expect(offScale).toEqual([]);
  });

  // Measured in a browser at the dock's real width, which narrows with the
  // window well below the 429px design frame: a three-digit "+ 128 yours"
  // wrapped "CURRENT SETUP" onto a second line and the card silently grew a
  // row. The heading must clip instead.
  it('keeps the setup card eyebrow on one line', () => {
    const rule = css.match(/\.current-setup-eyebrow\s*\{[^}]*\}/);
    expect(rule).not.toBeNull();
    expect(rule![0]).toMatch(/white-space:\s*nowrap/);
    const label = css.match(/\.current-setup-eyebrow\s*>\s*span:first-child\s*\{[^}]*\}/);
    expect(label).not.toBeNull();
    expect(label![0]).toMatch(/text-overflow:\s*ellipsis/);
